import '../interfaces/IHistoryStateTrackerBase.sol';
import '../interfaces/IEnosysDexV3Factory.sol'; 
import '../interfaces/external/IFtsoRewardRedistributor.sol';
import '../interfaces/external/IWNat.sol';

import '../interfaces/external/IFlareContractRegistry.sol';
import '../interfaces/external/IClaimSetupManager.sol';

library DelegationHelper {
    IFlareContractRegistry internal constant flareContractRegistry =
        IFlareContractRegistry(0xaD67FE66660Fb8dFE9d6b1b4240d8650e30F6019);

    function delegate(address factory, address wnat) external {
        address ftsoRewardRedistributor = IEnosysDexV3Factory(factory).ftsoRewardRedistributor();
        IFtsoRewardRedistributor.DelegateInfo[] memory delegatesInfo = IFtsoRewardRedistributor(ftsoRewardRedistributor).getDelegates(
            address(this)
        );
        IWNat(wnat).undelegateAll();
        for (uint256 i = 0; i < delegatesInfo.length; i++) {
            //batchDelegate not supported in Songbird and Coston1
            IWNat(wnat).delegate(delegatesInfo[i].to, delegatesInfo[i].bips);
        }
    }

    function setClaimExecutorAndRecipient(address factory) external {
        IClaimSetupManager claimSetupManager = IClaimSetupManager(
            flareContractRegistry.getContractAddressByName("ClaimSetupManager")
        );
        address ftsoRewardRedistributor = IEnosysDexV3Factory(factory).ftsoRewardRedistributor();
        address monthlyAirdropRedistributor = IEnosysDexV3Factory(factory).monthlyAirdropRedistributor();
        bool isMonthlyAirdropPresent = monthlyAirdropRedistributor != address(0);

        address[] memory executorsAndRecipients = new address[](isMonthlyAirdropPresent ? 2 : 1);
        executorsAndRecipients[0] = address(ftsoRewardRedistributor);
        if (isMonthlyAirdropPresent) {
            executorsAndRecipients[1] = address(monthlyAirdropRedistributor);
        }

        claimSetupManager.setClaimExecutors(executorsAndRecipients);
        claimSetupManager.setAllowedClaimRecipients(executorsAndRecipients);
    }

    function execute(address to, bytes calldata _calldata) external returns (bytes memory) {
        (bool success, bytes memory result) = to.call(_calldata);
        if (success) { 
            return result;
        } else {
            if (result.length < 4) revert("DelegationHelper: unexpected revert during execute call");
            bytes4 sig =
                result[0] |
                (bytes4(result[1]) >> 8) |
                (bytes4(result[2]) >> 16) |
                (bytes4(result[3]) >> 24);
            if (sig == 0x08c379a0) { //0x08c379a0 is the 'selector' of Error(string)
                for (uint256 i; i < result.length-4;i++) {
                    result[i] = result[i+4];
                }
                string memory text = abi.decode(result, (string));
                revert(text);
            } else {
                revert("DelegationHelper: unexpected final revert during execute call");
            }
        }
    }
}

