pragma solidity ^0.7.0;

/// @title Track history state of any values by block number
interface IHistoryStateTrackerBase {
    /// @dev Emitted when the history state value for a key is updated
    /// @param key the bytes32 key for which the history state was updated
    /// @param checkpointIndex the block number or epoch number at which the history state was updated
    /// @param value the new history state value
    event UpdateHistoryState(bytes32 indexed key, uint256 checkpointIndex, uint256 value);

    /// @dev Update the history state value provided in `amount` for the `key`
    /// @param key the bytes32 key for which the history state should be updated
    /// @param amount the amount to update the history state with
    /// @notice Only callable by the address with UPDATER_ROLE
    function updateHistoryState(bytes32 key, uint256 amount) external;

    /// @dev Queries the history state value for the `key` at a specific `checkpointIndex`
    /// @param key the bytes32 key for which the history state will be retrieved
    /// @param checkpointIndex the block number at which the history state should be retrieved
    /// @return the history state value at current checkpoint index.
    function stateOfAt(bytes32 key, uint256 checkpointIndex) external view returns (uint256);

    /// @dev Get the history state value for the `key` at the current block number
    /// @param key the bytes32 key for which the history state should be retrieved
    /// @return the history state value at the current checkpoint index.
    function stateOfAtNow(bytes32 key) external view returns (uint256);

    /// @dev Set the contract that is allowed to call history cleaning methods.
    /// @param cleanerContract The address of the cleaner contract.
    function setCleanerContract(address cleanerContract) external;

    /// @dev Set the cleanup checkpoint index, checkpoints after that index an be deleted.
    /// @param _checkpointIndex the checkpoint index to set
    function setCleanupCheckpoint(uint256 _checkpointIndex) external;

    /// @dev Delete state checkpoints that expired (i.e. are before `cleanupBlockNumber`).
    /// Method can only be called from the `cleanerContract` (which may be a proxy to external cleaners).
    /// @param key state key
    /// @param count maximum number of checkpoints to delete
    /// @return the number of checkpoints deleted
    function stateHistoryCleanup(bytes32 key, uint256 count) external returns (uint256);

    /// @dev Get the cleanup block number.
    function getCleanupCheckpointIndex() external view returns (uint256);

    /// @dev Get the current checkpoint index.
    function getCurrentCheckpointIndex() external view returns (uint64);
}

