/// @title NFT Balance Tracker
/// @notice This interface is used to get information about the underlying token balance for an NFT
/// and total supply for a pool
interface INftBalanceTracker {
    /// @notice Is provided address approved or owner of the NFT
    /// @param spender The address to check
    /// @param tokenId The ID of the NFT
    /// @return True if spender is approved or owner of the NFT
    function isApprovedOrOwner(address spender, uint256 tokenId) external view returns (bool);

    /// @notice Get the intermediate owner of the token that corresponds for the provided NFT
    /// @dev For EnosysDexV3 it will return the address of the corresponding NFT position pool 
    /// @dev Returns address(0) if NFT has no an intermediate token owner
    /// @param nftId The ID of the NFT
    /// @return The address of the token intermediate owner
    function getNftUnderlyingTokenOwner(uint256 nftId) external view returns (address);

    /// @notice Get the underlying token balance for provided NFT at the provided block number
    /// @param nftId The ID of the NFT
    /// @param blockNumber The block number to get the token balance at
    /// @return The token balance of the NFT at the specified block number
    function tokenBalanceOfAt(uint256 nftId, address token, uint256 blockNumber) external view returns (uint256);

    /// @notice Get the underlying token total supply for the provided owner at the provided block number
    /// @param tokenOwner The address of the token owner
    /// @param blockNumber The block number to get the total supply at
    /// @return The token total supply of the owner at the specified block number
    function tokenTotalSupplyAt(address tokenOwner, address token, uint256 blockNumber) external view returns (uint256);
}

