        (uint16 cardinality, uint16 cardinalityNext) = Oracle.initialize(observations, _blockTimestamp());

        uint8 defaultFeeProtocol = IEnosysDexV3Factory(factory).protocolFee();
        slot0 = Slot0({
            sqrtPriceX96: sqrtPriceX96,
            tick: tick,
            observationIndex: 0,
            observationCardinality: cardinality,
            observationCardinalityNext: cardinalityNext,
            feeProtocol: defaultFeeProtocol + (defaultFeeProtocol << 4),
            unlocked: true
        });
