    /// @dev The token amount change represent the token amount that corresponds to the liquidity in the pools
    // and doesn't include the token that is going to be paid as collected fees
    function _processTokenLiquidityChangeOnModifyPosition(int amount, address token) internal {
        uint256 amountToUpdate;
        bool isIncrease; //false by default
        if (amount > 0) {
            amountToUpdate = uint256(amount);
            isIncrease = true;
        } else {
            amountToUpdate = uint256(-amount);
